//! Padding-boundary known-answer tests.
//!
//! FIPS 180-4 §5.1 makes the digest a function of the message length as well as
//! its bytes, and the interesting lengths are the ones where the padding
//! decision changes:
//!
//! | Family | Block | Length field | Fits in the same block iff |
//! |---|---|---|---|
//! | SHA-224/256 | 64 B | 8 B | `len mod 64 <= 55` |
//! | SHA-384/512 | 128 B | 16 B | `len mod 128 <= 111` |
//!
//! So 55/56, 63/64, 119/120 and 127/128 are the SHA-256 transitions, and
//! 111/112, 127/128, 239/240 and 255/256 the SHA-512 ones. Every one of those,
//! plus their neighbours and several multi-block lengths, is pinned below.
//!
//! # Provenance of the expected values — read this before trusting them
//!
//! These were **generated by CPython's `hashlib`** (OpenSSL), which is a third
//! implementation independent of both this crate and the incumbent `sha2`
//! crate. They are therefore genuine cross-implementation evidence, not a
//! snapshot of this crate's own output — a table produced by running the code
//! under test proves only that it is deterministic.
//!
//! The message at length `n` is `msg[i] = (i * 31 + 7) mod 256`, chosen so that
//! no two lengths share a prefix relationship that could mask an off-by-one in
//! the buffered tail.

use trust_sha2::{Digest, Sha256, Sha512};

/// The message used at every length. Must stay in step with the generator
/// described in the module docs.
fn message(length: usize) -> Vec<u8> {
    (0..length).map(|i| ((i * 31 + 7) & 0xff) as u8).collect()
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        use std::fmt::Write as _;
        write!(&mut out, "{byte:02x}").expect("String write cannot fail");
    }
    out
}

