#[test]
fn sha256_padding_boundaries() {
    for &(length, expected) in SHA256_BOUNDARY {
        let digest = Sha256::digest(message(length));
        assert_eq!(hex(&digest), expected, "SHA-256 disagrees at length {length}");
    }
}

#[test]
fn sha512_padding_boundaries() {
    for &(length, expected) in SHA512_BOUNDARY {
        let digest = Sha512::digest(message(length));
        assert_eq!(hex(&digest), expected, "SHA-512 disagrees at length {length}");
    }
}

/// The table must actually contain the lengths its docs claim, or a future
/// edit could delete the interesting rows and leave a green test. A silent
/// instrument reads as a clean result.
#[test]
fn boundary_table_covers_the_transitions() {
    let sha256_lengths: Vec<usize> = SHA256_BOUNDARY.iter().map(|&(n, _)| n).collect();
    for required in [0usize, 55, 56, 63, 64, 119, 120, 127, 128] {
        assert!(
            sha256_lengths.contains(&required),
            "SHA-256 boundary table lost the length-{required} row"
        );
    }

    let sha512_lengths: Vec<usize> = SHA512_BOUNDARY.iter().map(|&(n, _)| n).collect();
    for required in [0usize, 55, 56, 63, 64, 111, 112, 119, 120, 127, 128, 239, 240, 255, 256] {
        assert!(
            sha512_lengths.contains(&required),
            "SHA-512 boundary table lost the length-{required} row"
        );
    }
}
